-- regenerate data355.json (not committed: it holds full debate rounds). Save the json_build_object value as data355.json.
select json_build_object('rounds',(select json_agg(json_build_object('run',run_token,'CR1',claude_r1,'CR2',claude_r2,'CR3',engine_r3,'CR4',defender_r4,'DR1',engine_r1,'DR2',engine_r2,'DR3',challenger_r3,'DR4',challenger_r4)) from debate_results where run_token ~ '37812|37891'),
'logs',(select json_agg(json_build_object('id',id,'run',run_token,'rule',rule,'seat',seat,'item',item,'fl',flagged_line,'cr',cure_reason,'fr',full_reply)) from debate_enforcer_log where run_token ~ '37812|37891' and kind='enforcer_check' and rule in ('E-COL','E-HOLD')),
'verses',(select json_agg(json_build_object('book',book,'chapter',chapter,'verse',verse,'text',text)) from kjv_verses where (book,chapter,verse) in (('2 Samuel',7,12),('Matthew',1,20),('Luke',1,35),('Acts',2,30),('Matthew',1,24),('Matthew',1,25),('Romans',1,3),('Matthew',1,18),('Luke',2,48),('Luke',1,27),('Luke',3,23),('Matthew',1,16),('Luke',1,34),('Matthew',1,19),('Isaiah',7,14),('Galatians',4,4))));
